"use strict";
// Polices du Chess Edit (SIL Open Font License 1.1, paquets npm @fontsource) : Bebas Neue (titres, très condensée) + Oswald 500 / 700 (bulles, noms). woff2 en base64, enregistrées par ENOS.editFonts.ready().
window.ENOS_EDITFONTS = {"bebas": "", "oswald5": "", "oswald7": ""};
(() => {
  const E = window.ENOS = window.ENOS || {}; let p = null;
  E.editFonts = { ready() { if (p) return p; p = (async () => { if (typeof FontFace !== "function" || !document.fonts) return false; const F = window.ENOS_EDITFONTS || {}, bin = (b) => { const r = atob(b), u = new Uint8Array(r.length); for (let i = 0; i < r.length; i++) u[i] = r.charCodeAt(i); return u.buffer; };
    const list = [["Bebas Neue", F.bebas, "400"], ["Oswald", F.oswald5, "500"], ["Oswald", F.oswald7, "700"]].filter((x) => x[1]);
    await Promise.all(list.map(async ([fam, b, w]) => { try { const f = new FontFace(fam, bin(b), { weight: w }); await f.load(); document.fonts.add(f); } catch (e) { /* police facultative : repli Impact / system-ui */ } })); return true; })(); return p; } };
})();
